# Demo2 output based on upper panel A and lower B aligned. Enumerate output fill markers against A/B transformed positions, test row/column flips
A=[[4,6,6,4,6,6,6],[6,6,6,4,6,4,6],[6,4,6,4,6,4,6],[6,6,6,4,4,4,4],[6,6,6,6,4,6,6]]
B=[[8,4,8,8,4,8,4],[4,4,4,4,8,4,8],[4,4,8,4,8,8,4],[4,4,4,4,4,4,8],[8,4,4,8,4,4,4]]
O={(1,3),(1,5),(2,1),(2,3),(3,3),(3,4),(3,5),(4,3)}
for flipr in [False,True]:
 for flipc in [False,True]:
  for valA in [4,6]:
   for valB in [4,8]:
    coords=set()
    for r in range(5):
     for c in range(7):
      rr=4-r if flipr else r; cc=6-c if flipc else c
      if A[r][c]==valA and B[rr][cc]==valB: coords.add((r,c))
    score=len(coords&O)-len(coords-O)
    if len(coords&O)>=5: print(flipr,flipc,valA,valB,coords&O, 'extra',coords-O)
PY

